# ===================================================================== H18
C18 = [
("s4","Waar staat ITU voor en waar is de organisatie gevestigd?","International Telecommunication Union, in Genève."),
("s4","Wat regelt de ITU?","Wereldwijde afspraken over frequentieruimte, roepletters per land, klassen van uitzending en Q-codes (Radio Regulations)."),
("s4","In welke ITU-regio ligt Nederland en welke gebieden horen bij de drie regio's?","Nederland ligt in regio I. Regio I: Europa, Afrika en een deel van Azië (incl. voormalige Sovjet-Unie). Regio II: Noord- en Zuid-Amerika. Regio III: Zuidoost-Azië, Australië, Oceanië (incl. Nieuw-Zeeland)."),
("s5","Wat is CEPT en waarvoor heb je het als zendamateur nodig?","Een Europese organisatie voor post en telecommunicatie. Via CEPT-aanbevelingen mag je tijdelijk in het buitenland zenden zonder aparte vergunning."),
("s6","Waar staat IARU voor en wat doet de organisatie?","International Amateur Radio Union: vertegenwoordigt de amateurs bij de ITU (waarnemer) en maakt bandplannen."),
("s6","Welke status hebben IARU-bandplannen?","Aanbeveling (geen wet), om onderlinge storing te beperken."),
("s7","Wat is HAREC?","Harmonised Amateur Radio Examination Certificate: een examenprogramma (van CEPT) dat de technische stof van zendexamens in verschillende landen gelijktrekt. Geen organisatie."),
("s9","Wat zijn Q-codes?","Codes van 3 letters die met een Q beginnen. QRA t/m QUZ zijn via de ITU gestandaardiseerd. Met vraagteken is het een vraag, zonder vraagteken een antwoord of melding."),
("s10","QRK?","Wat is de neembaarheid van mijn signalen? (K van kwaliteit)"),
("s10","QRM?","Wordt u gestoord? Antwoord: ik ondervind storing (M van man made interference)."),
("s10","QRN?","Heeft u last van atmosferische storingen? (N van natural)"),
("s10","QRO?","Zal ik mijn zendvermogen verhogen? (O van ophogen)"),
("s10","QRP?","Zal ik mijn zendvermogen verminderen? (P van petty, klein). Ook gebruikt voor werken met klein vermogen."),
("s10","QRT?","Zal ik ophouden? Antwoord: houd op (T in sTop)."),
("s10","QRV?","Bent u beschikbaar? (V uit available)"),
("s10","QRX?","Op welk tijdstip zult u mij weer roepen? Antwoord: ik zal om … uur weer roepen."),
("s10","QRZ?","Door wie word ik geroepen? (Z van zijt gij)"),
("s10","QSB?","Verandert de sterkte van mijn signaal? (slenk en bult: fading)"),
("s10","QSL?","Wilt u mij de ontvangst bevestigen? Antwoord: ik bevestig u de ontvangst."),
("s10","QSO?","Kunt u rechtstreeks werken met …? Een QSO is ook een verbinding."),
("s10","QSY?","Zal ik op een andere frequentie zenden? Antwoord: ga op een andere frequentie zenden."),
("s10","QTH?","Wat is uw positie (plaats)? (H van home)"),
("s11","Wat betekent CQ?","Algemene oproep aan alle stations."),
("s11","Wat betekent DE?","“Van”: scheidt de roepletters van het aangeroepen en het aanroepende station."),
("s11","Wat betekent K en wat betekent AR?","K = uitnodiging om te zenden (over). AR = einde uitzending of bericht."),
("s11","Wat betekent SK?","Einde verbinding / sluiten station (silent key; ook gebruikt voor het overlijden van een amateur)."),
("s11","Wat betekent BK?","Een lopende uitzending onderbreken (break)."),
("s11","Wat betekent RST?","Ontvangstrapport in drie cijfers: leesbaarheid (readability), signaalsterkte (strength) en toonkwaliteit (tone)."),
("s11","Wat betekenen R, RX, TX, TRX, UR, PSE, MSG?","R = ontvangen, RX = ontvanger, TX = zender, TRX = zendontvanger, UR = uw/jouw, PSE = alstublieft, MSG = bericht."),
("s12","Wat is het internationale noodsignaal in telegrafie en in telefonie?","Telegrafie: SOS (aan elkaar geseind). Telefonie: MAYDAY."),
("s12","Wat doe je als je een noodsignaal opvangt?","Nagaan of het beantwoord wordt, geen lopend noodverkeer storen en zo nodig de bevoegde instanties (112) informeren. Valse noodsignalen uitzenden is verboden en strafbaar."),
("s14","Welke letterserie is aan Nederland toegewezen voor radiostations, en welke prefixen gebruikt de Amateurdienst?","Letterserie PAA t/m PIZ. Amateurs: PA t/m PI, gevolgd door een cijfer."),
("s14","Welke cijfers horen bij individuele amateurs, en wat betekent cijfer 6?","0 t/m 5 en 7 t/m 9 voor individuele zendamateurs, 6 voor bijzondere evenementen en conteststations."),
("s14","Aan welke prefix herken je de N-registratie?","PD."),
("s14","Waar gebruikt men PI, PJ en PZ?","PI: verenigingen, onderwijsinstellingen en experimenten. PJ: Caraïbisch Nederland. PZ: Suriname."),
("s15","Uit welke delen bestaan roepletters en welke suffixen zijn uitgesloten?","Prefix (bijv. PE1) + suffix van 1 tot 3 letters. SOS en QOA t/m QUZ zijn uitgesloten."),
("s16","Hoe identificeert een buitenlandse CEPT-amateur zich in Nederland?","Met de eigen roepletters voorafgegaan door PA/ (N-klasse: PD/)."),
("s17","Welk alfabet gebruik je om roepletters te spellen?","Het internationale spellingsalfabet (Alfa, Bravo, Charlie, …), ook bij de roepletters tijdens een uitzending."),
("s17","Spelwoorden voor A t/m M?","Alfa, Bravo, Charlie, Delta, Echo, Foxtrot, Golf, Hotel, India, Juliett, Kilo, Lima, Mike."),
("s17","Spelwoorden voor N t/m Z?","November, Oscar, Papa, Quebec, Romeo, Sierra, Tango, Uniform, Victor, Whiskey, X-ray, Yankee, Zulu."),
("s20","Wat is de definitie van de amateurdienst (ITU S1.56)?","Een radiodienst van zelfontwikkeling, onderlinge radiogemeenschap en technische onderzoekingen, uitgeoefend door radioamateurs: bevoegde personen die geïnteresseerd zijn in de radiotechniek, uitsluitend met een persoonlijk oogmerk en zonder geldelijk belang."),
("s21","Mag je met amateurs in andere landen verbindingen maken?","Ja, tenzij de administratie van een van beide landen bezwaar heeft aangegeven."),
("s21","Waarover mogen internationale amateurverbindingen gaan?","Alleen over zaken eigen aan de amateurdienst (zend- en luisterhobby) en opmerkingen van persoonlijke aard."),
("s21","Mag je geheimtaal of versleuteling gebruiken?","Nee. Alleen stuursignalen voor amateursatellieten mogen gecodeerd zijn."),
("s21","Wanneer mag een amateurstation communicatie namens derden verzorgen?","Alleen bij noodtoestanden of hulp bij rampen, en alleen als de overheid dat toestaat."),
("s21","Hoe vaak moet je je roepletters uitzenden?","Aan het begin en het eind van elke uitzending en ten minste eenmaal per periode van 5 minuten."),
("s21","Is Morse-vaardigheid in Nederland nodig voor een registratie?","Nee, die eis is afgeschaft. Elk land beslist daar zelf over."),
("s23","Wat is een klasse van uitzending (KVU)?","Een code van drie tekens: letter, cijfer, letter. Internationaal Class Of Emission (COE). Amateurs spreken meestal van mode."),
("s27","Wat betekent de eerste letter van een KVU?","De soort modulatie van de zender: N ongemoduleerd, A amplitudemodulatie (AM), H EZB met volledige draaggolf, J EZB met onderdrukte draaggolf (SSB), R EZB met gedeeltelijk onderdrukte draaggolf, C restzijband, F frequentiemodulatie (FM), G fasemodulatie (PM)."),
("s27","Wat betekent het cijfer in een KVU?","0 geen modulatie. 1 enkel kanaal, niet-analoog, zonder hulpdraaggolf. 2 enkel kanaal, niet-analoog, mét hulpdraaggolf. 3 enkel kanaal, analoge informatie."),
("s27","Wat betekent de laatste letter van een KVU?","De soort informatie: N geen, A morse (gehoor), B telegrafie voor automatische ontvangst (RTTY, PSK), C fax/SSTV, D data (packet), E telefonie (spraak), F televisie."),
("s27","Welke letter in een KVU hoort bij SSB (EZB) met onderdrukte draaggolf?","J (bijvoorbeeld J3E voor spraak)."),
("s27","Waar wordt de eerste letter van de KVU door bepaald bij een hulpdraaggolf?","Door de soort modulatie van de zender, niet die van de modem."),
("s28","A1A","Gewone CW: een aan/uit gesleutelde draaggolf met morse."),
("s28","J3E","Spraak in SSB (enkelzijband met onderdrukte draaggolf)."),
("s28","F3E","Spraak in FM."),
("s28","A3E","Spraak in AM."),
("s28","G3E","Spraak in fasemodulatie (PM)."),
("s28","H3E","Spraak in SSB met volledige draaggolf."),
("s28","J2B","RTTY via modem of geluidskaart in SSB. Ook PSK."),
("s28","F2B","RTTY via modem in FM (AFSK)."),
("s28","F1B","RTTY met rechtstreekse FSK van de draaggolf."),
("s28","F2D","Data in FM met hulpdraaggolf, zoals 1200 baud packet."),
("s28","F1D","Data in FM zonder hulpdraaggolf (snelheden boven 1200 baud)."),
("s28","G1D","Data in PM zonder hulpdraaggolf, zoals DATV met QPSK."),
("s28","J2D","Data in SSB met modem of geluidskaart."),
("s28","F2A","Morse in FM met hulpdraaggolf (toon)."),
("s28","J2A","Morse in SSB met een toon."),
("s28","F1A","CW door FSK van de draaggolf (veel bij bakens)."),
("s28","F2C en J2C","Fax of SSTV in FM respectievelijk SSB."),
("s28","C3F en F3F","Televisie: C3F in restzijband (70 cm), F3F in FM (23 cm, 13 cm, 3 cm)."),
("s29","Waarover gaan de CEPT-aanbevelingen T/R 61-01, T/R 61-02 en ECC-REC(05)06?","T/R 61-01: gebruik van je registratie in het buitenland. T/R 61-02: HAREC, harmonisatie van zendexamens. ECC-REC(05)06: N-amateurs (wederzijdse erkenning en tijdelijk gebruik)."),
("s29","Wat zijn de regels bij tijdelijk gebruik in het buitenland (T/R 61-01)?","Maximaal 3 maanden, CEPT-licentie bij je en op verzoek tonen, bevoegdheden zijn de optelsom van thuis en gastland, en identificatie met landencode + / + eigen roepletters (bijvoorbeeld DO/)."),
("s31","Wie is de bevoegde minister voor de Telecommunicatiewet?","De Minister van Economische Zaken."),
("s31","Wat is een radioapparaat volgens de wet?","Een elektrisch of elektronisch product dat doelbewust radiogolven uitzendt of ontvangt, of dat met een accessoire (antenne, microfoon, voeding) daartoe kan worden aangevuld."),
("s31","Wat kan de minister opleggen als je de regels overtreedt?","Een geheel of gedeeltelijk zendverbod. Inbeslagname wordt in de wet niet genoemd, dus dat antwoord is altijd fout."),
("s33","Wat moet je doen voor je op amateurfrequenties mag zenden?","Eerst het examen halen en je laten registreren (melding) bij RDI (DigiD nodig). Pas met je registratiebewijs mag je uitkomen."),
("s33","Wat krijg je bij registratie, naast het bewijs?","Roepletters (een call) waarmee je je station identificeert."),
("s34","Wie is verantwoordelijk als een ander jouw zender bedient?","Jijzelf: je moet ervoor zorgen dat de voorschriften worden nageleefd."),
("s34","Waar moet het registratiebewijs liggen?","Bij het radioapparaat."),
("s34","Wat moet je doen bij gebruik van een frequentie waarop je een secundaire status hebt?","Altijd voorrang geven aan diensten met een primaire status."),
("s34","Mag je ontoelaatbare storing veroorzaken of valse noodseinen uitzenden?","Nee, geen van beide."),
("s34","Mag je reclame of media-aanbod uitzenden?","Nee, het uitzenden van media-aanbod of reclameboodschappen is niet toegestaan."),
("s34","Hoe moet de call bij data- en beeldoverdracht worden uitgezonden?","Na demodulatie leesbaar in schrift zichtbaar. Lukt dat niet, dan met spraak of morse."),
("s34","Met wie mag je radioverbindingen maken?","Alleen met andere gebruikers van frequentieruimte met de bestemming amateur of amateursatelliet."),
("s34","Mag je je zender onbeheerd laten werken?","Je bedient hem zelf. Op afstand mag, maar alleen jij mag hem bedienen. Bij groepsactiviteiten van verenigingen (vossenjacht) mogen zenders onbeheerd worden achtergelaten."),
("s35","Wat is verplicht voor een vast opgestelde antenne?","Registratie in het antenneregister (Antennebureau, RDI). Gegevens: toepassing, hoogte en coördinaten."),
("s36","Wat is EMC?","Elektromagnetische compatibiliteit: het vermogen van uitrusting om bevredigend te functioneren in haar elektromagnetische omgeving zonder zelf ontoelaatbare verstoringen te veroorzaken."),
("s38","Wat is een primaire dienst en wat een secundaire dienst?","Primair: hoofdbewoner met de hoogste rechten. Secundair: mag geen hinderlijke storing veroorzaken aan primair, heeft geen bescherming tegen primair en mag niet gestoord worden door andere secundaire diensten."),
("s38","Wat is de NIB-status?","Non-Interference Basis: laagste rang. Je mag de band gebruiken zolang je geen storing veroorzaakt, maar je moet storing van primaire en secundaire stations accepteren."),
("s38","Hoe wordt zendvermogen gedefinieerd?","Het door de direct met de antenne te koppelen trap afgegeven gemiddelde vermogen over een periode van de HF-wisselspanning tijdens het maximum van de omhullende (PEP)."),
("s39","Welke vermogens gelden voor N-registratie?","100 W (PEP) op 7, 14 en 28 MHz en 25 W op 144–146 en 430–438 MHz."),
("s40","Welk vermogen geldt voor F-registratie op de HF-banden en op 144–146 MHz?","400 W (PEP) op 1,81–29,7 MHz (bijzondere bepalingen daargelaten) en op 144–146 MHz."),
("s40","Welke beperking geldt op 50 MHz en 70 MHz voor F?","50,0–50,45 MHz: 120 W, alleen A1A en J3E (secundair); 50,45–52 MHz 30 W; 70–70,5 MHz 50 W. Duplexverbindingen niet toegestaan op 50,45–52 en 70 MHz."),
("s40","Wat is een duplexverbinding en wat is simplex?","Duplex: twee stations zenden en ontvangen op verschillende frequenties. Simplex: dezelfde frequentie. De meeste verbindingen zijn simplex."),
("s40","Welk vermogen mag een F-amateur op 23 cm en hoger?","120 W (PEP). Op 2400–2450 MHz alleen voor satellietverkeer (aarde naar ruimte)."),
("s40","Wat geldt voor 135,7–137,8 kHz?","Alleen klasse A1A, 400 W, secundaire status."),
("s43","Hoe ga je om met klachten over storing?","Word nooit boos, werk in redelijk overleg aan een oplossing en controleer op een voor de klager duidelijke manier of de storing van jou komt."),
("s44","Mag je een klager adviseren een klacht bij RDI in te dienen?","Nee, dat is onbehoorlijk. Je hoort mee te werken aan het opheffen of beperken van de storing."),
("s45","Wat doen IARU-bandplannen?","Ze geven aan welke soort uitzending het best in welk deel van een band kan plaatsvinden. Je houdt je er aan."),
("s46","Wat doe je met je zendvermogen?","Gebruik niet meer dan nodig. Vermijd overmodulatie en splatter en test met een kunstantenne (dummyload)."),
("s48","Welke zijband gebruik je voor SSB-spraak onder en boven 10 MHz?","Onder 10 MHz de onderste zijband (LSB), erboven de bovenste (USB)."),
("s48","Mag een groep amateurs een frequentie voor zich claimen?","Nee, niemand heeft een exclusief recht op een frequentie."),
("s48","Wanneer beantwoord je een “CQ DX” niet?","Als het station naar de maatstaven van de band in de buurt zit (een Fransman op 20 m). Voor oproepen aan een ander werelddeel, zoals CQ Africa, geldt hetzelfde."),
("s49","Hoe gedraag je je op de band?","Geen krachttermen, geduld hebben en niet terechtwijzen (het ‘Korps Bandpolitie’ negeer je). Zorg voor goede verstaanbaarheid."),
("s50","Wat betekenen de cijfers in een RST-rapport?","R 1–5 (leesbaarheid), S 1–9 (signaalsterkte), T 1–9 (toon). Bij spraak alleen R en S, bijvoorbeeld 57."),
("s50","Wat betekent RST 349?","Met moeite neembaar signaal (3), redelijk van sterkte (4) en zuivere strakke toon (9)."),
("s50","Hoe geef je een ontvangstrapport?","Eerlijk, met je S-meter. Geen 59 als het tegenstation nauwelijks te verstaan is."),
("s51","Hoe antwoord je op een CQ-oproep?","Eerst de call van het andere station, dan “dit is” en je eigen call, gespeld volgens het spellingsalfabet."),
("s51","Wat doe je voor je zelf CQ roept?","Luisteren en zeker weten dat de frequentie vrij is (niet in gebruik bij stations die je niet hoort), dan eventueel vragen of de frequentie vrij is."),
("s51","Wat is een pile-up en wat doe je bij een contest?","Een pile-up is een groep stations die één gewild station tegelijk aanroept. Bij contesten geef je vaak maar één keer je call en luister je eerst naar de rapportuitwisseling."),
("s54","Zijn er leeftijdsgrenzen voor een registratie?","Nee, die zijn sinds 17 juni 2021 vervallen. Eerder 12 jaar (N) en 14 jaar (F)."),
]

