RW18 = {}

def build(chap, C, F, DR, RW):
    f = ROOT / 'data' / 'theorie' / f'hoofdstuk-{chap}.json'
    d = json.loads(f.read_text(encoding='utf-8'))
    ids = {s['id'] for s in d['sections']}
    for sec, *_ in C: assert sec in ids, (chap, 'card', sec)
    for it in DR: assert it['sec'] in ids, (chap, 'drill', it['sec'])
    d['cards'] = [{"id": f"c{i+1}", "sec": s, "q": q, "a": a} for i, (s, q, a) in enumerate(C)]
    d['formulas'] = F
    out = []
    for it in DR:
        x = {k: it[k] for k in ('id', 'sec', 'name', 'where', 'f') if k in it}
        x['cloze'] = [{"q": q, "a": a, "w": w} for q, a, w in it.get('cloze', [])]
        if it.get('gen'): x['gen'] = it['gen']
        if it.get('pairs'):
            x['pairs'] = [{"q": q, "a": a} for q, a in it['pairs']]; x['ask'] = it['ask']
            if it.get('rev'): x['askRev'] = it['askRev']
        if it['id'] in RW: x['rewrite'] = [{"base": b, "ask": a, "a": r, "w": w} for b, a, r, w in RW[it['id']]]
        out.append(x)
    d['drill'] = out
    f.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding='utf-8')
    print(f'H{chap}:', len(d['cards']), 'kaarten,', len(out), 'oefen-items,', sum(len(g['items']) for g in F), 'regels naslag')

build(17, C17, F17, DR17, RW17)
build(18, C18, F18, DR18, RW18)
